import argparse
import sys

from question_bank import DEFAULT_BANK, load_bank
from quiz import Quiz


def build_parser():
    parser = argparse.ArgumentParser(description="Trivia quiz program")
    parser.add_argument("--bank", help="Path to a JSON question bank file")
    parser.add_argument("--topic", help="Only ask questions on this topic")
    parser.add_argument("--count", type=int, help="Number of questions to ask")
    parser.add_argument("--shuffle", action="store_true",
                        help="Shuffle question order")
    parser.add_argument("--show-answers", action="store_true",
                        help="Show correct answers after the quiz")
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        questions = load_bank(args.bank) if args.bank else list(DEFAULT_BANK)
        if args.topic:
            questions = [q for q in questions
                         if q.topic.lower() == args.topic.lower()]
        if not questions:
            print("Error: no questions available for the selected options.")
            return 1
        quiz = Quiz(questions, shuffle=args.shuffle, count=args.count)
    except (OSError, ValueError) as exc:
        print(f"Error: {exc}")
        return 1
    quiz.run()
    quiz.report(show_answers=args.show_answers or None)
    return 0


if __name__ == "__main__":
    sys.exit(main())
