"""Core quiz engine: Question model, interactive loop, and scoring."""

import random


class Question:
    """A single trivia question (multiple-choice or short answer)."""

    def __init__(self, text, answer, choices=None, topic="General"):
        self.text = str(text)
        self.answer = str(answer).strip()
        self.choices = [str(c) for c in choices] if choices else None
        self.topic = str(topic)

    @property
    def is_multiple_choice(self):
        return bool(self.choices)

    @staticmethod
    def normalize(value):
        return " ".join(str(value).strip().lower().split())

    def resolve_choice(self, response):
        """Map a numeric/letter multiple-choice selection to its choice text."""
        if not self.is_multiple_choice:
            return response
        value = str(response).strip()
        if value.isdigit():
            index = int(value) - 1
            if 0 <= index < len(self.choices):
                return self.choices[index]
        if len(value) == 1 and value.isalpha():
            index = ord(value.lower()) - ord("a")
            if 0 <= index < len(self.choices):
                return self.choices[index]
        return value

    def check(self, response):
        return self.normalize(response) == self.normalize(self.answer)

    def prompt(self):
        lines = [f"[{self.topic}] {self.text}"]
        if self.is_multiple_choice:
            for index, choice in enumerate(self.choices):
                lines.append(f"  {chr(97 + index)}) {choice}")
            lines.append("Your choice (letter, number, or full text):")
        else:
            lines.append("Your answer:")
        return "\n".join(lines)

    def display_answer(self):
        if self.is_multiple_choice:
            for index, choice in enumerate(self.choices):
                if self.normalize(choice) == self.normalize(self.answer):
                    return f"{chr(97 + index)}) {self.answer}"
        return self.answer


class Quiz:
    """Runs a quiz session over a list of Question objects and tracks score."""

    def __init__(self, questions, shuffle=False, count=None):
        pool = list(questions)
        if shuffle:
            random.shuffle(pool)
        if count is not None:
            if count <= 0:
                raise ValueError("--count must be a positive integer")
            pool = pool[:count]
        if not pool:
            raise ValueError("No questions to build a quiz from")
        self.questions = pool
        self.results = []  # (question, response, is_correct)

    def run(self):
        total = len(self.questions)
        print("=" * 52)
        print("TRIVIA QUIZ".center(52))
        print("=" * 52)
        print(f"You will answer {total} questions. Type 'q' to quit early.\n")
        for number, question in enumerate(self.questions, 1):
            print(f"Question {number} of {total}")
            print(question.prompt())
            response = self._read_response()
            if response is None:
                print("\nQuiz aborted by user.")
                break
            correct = question.check(question.resolve_choice(response))
            self.results.append((question, response, correct))
            print("Correct!\n" if correct else "Incorrect.\n")

    @staticmethod
    def _read_response():
        while True:
            try:
                response = input("> ").strip()
            except (EOFError, KeyboardInterrupt):
                print()
                return None
            if response.lower() == "q":
                return None
            if response:
                return response
            print("Please enter a non-empty answer (or 'q' to quit).")

    @property
    def score(self):
        return sum(1 for _, _, correct in self.results if correct)

    def report(self, show_answers=None):
        answered = len(self.results)
        total = len(self.questions)
        print("=" * 52)
        print("QUIZ RESULTS".center(52))
        print("=" * 52)
        print(f"Total correct answers: {self.score} out of {total}")
        if answered < total:
            print(f"(Answered {answered} of {total} questions before quitting.)")
        if answered:
            print(f"Accuracy: {100.0 * self.score / answered:.1f}%")
        if show_answers is None:
            show_answers = self._ask_show_answers()
        if show_answers:
            print("\nCorrect answers:")
            for number, (question, response, correct) in enumerate(self.results, 1):
                status = "Correct" if correct else "Incorrect"
                print(f"  {number}. [{status}] {question.text}")
                print(f"     Your answer: {response}")
                print(f"     Correct answer: {question.display_answer()}")

    @staticmethod
    def _ask_show_answers():
        try:
            reply = input("Show correct answers? (y/n): ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print()
            return False
        return reply in ("y", "yes")
